challenge_result.network_analysis:
{
  "summary": "The fired event and screener flags indicate a severe media plane failure. While call signaling appears partially active, user plane traffic is not flowing, pointing to either RTPEngine or UPF as the likely root cause, consistent with several high-similarity prior episodes.",
  "layer_status": {
    "ims": {
      "rating": "red",
      "evidence": [
        "derived.upf_activity_during_calls:drop"
      ],
      "note": "The primary symptom is the collapse of media activity (rtpengine, upf) during active calls, which is an IMS media plane function."
    },
    "core": {
      "rating": "yellow",
      "evidence": [
        "normalized.upf.gtp_indatapktn3upf_per_ue:shift",
        "normalized.upf.gtp_outdatapktn3upf_per_ue:shift"
      ],
      "note": "UPF, a core component, is a potential suspect and is showing anomalous traffic patterns. The SMF is also showing a spike in bearer counts."
    },
    "ran": {
      "rating": "green",
      "evidence": [],
      "note": "No direct evidence of a RAN failure."
    },
    "infrastructure": {
      "rating": "green",
      "evidence": [],
      "note": "Network topology and container status appear normal."
    }
  },
  "hypotheses": [
    {
      "id": "h1",
      "statement": "The media plane is broken at rtpengine, which is failing to relay RTP packets. This is strongly supported by the `upf_activity_during_calls_collapsed` event and is the ground truth in the highest-similarity prior episode (v7/ep_20260510_185748_call_quality_degradation).",
      "primary_suspect_nf": "rtpengine",
      "supporting_events": [
        "core.upf.activity_during_calls_collapsed"
      ],
      "explanatory_fit": 0.9,
      "falsification_probes": [
        "A `measure_rtt` probe from `upf` to `rtpengine` that shows no packet loss or abnormal latency would indicate the path is healthy, shifting suspicion away from rtpengine's network layer.",
        "Directly inspecting `rtpengine`'s kernel-level network statistics for packet drops on its interfaces. An absence of drops would disprove a network-level fault at rtpengine, as per lesson L04."
      ],
      "specificity": "specific"
    },
    {
      "id": "h2",
      "statement": "The UPF is the source of the data plane failure, dropping GTP-U packets and preventing media from reaching the rtpengine. This aligns with the `upf_activity_during_calls_collapsed` event and is supported by two high-similarity prior cases.",
      "primary_suspect_nf": "upf",
      "supporting_events": [
        "core.upf.activity_during_calls_collapsed"
      ],
      "explanatory_fit": 0.8,
      "falsification_probes": [
        "A `measure_rtt` probe from `rtpengine` to `upf` that shows no packet loss or latency would suggest the path to UPF is clean.",
        "Probing UPF's PFCP session state via `get_nf_metrics`. Healthy session state alongside zero throughput would point to an internal UPF forwarding issue."
      ],
      "specificity": "specific"
    }
  ]
}

challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "The media plane is broken at rtpengine, which is failing to relay RTP packets. This is strongly supported by the `upf_activity_during_calls_collapsed` event and is the ground truth in the highest-similarity prior episode (v7/ep_20260510_185748_call_quality_degradation).",
      "primary_suspect_nf": "rtpengine",
      "probes": [
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Returns rate-based MOS/loss/jitter alongside RTPEngine errors.",
          "expected_if_hypothesis_holds": "The `rtpengine.errors_per_second` metric shows a spike, indicating errors in the relay function.",
          "falsifying_observation": "The `rtpengine.errors_per_second` metric is zero or at its baseline, indicating no relay-loop errors are being reported by rtpengine.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "from='upf', to_ip='rtpengine'",
          "expected_if_hypothesis_holds": "No significant packet loss or latency is observed, which would indicate the network path to rtpengine is healthy and does not contradict the hypothesis.",
          "falsifying_observation": "High packet loss or latency is observed. This would suggest the problem lies in the network path to rtpengine, not within rtpengine itself.",
          "conflates_with": [
            "upf's networking stack",
            "the network fabric between upf and rtpengine"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "from='upf', to_ip='smf'",
          "expected_if_hypothesis_holds": "No significant packet loss or latency is observed. If the path to rtpengine is also healthy, it strengthens the focus on rtpengine as the source of the failure.",
          "falsifying_observation": "High packet loss or latency is observed. If the path to rtpengine also shows high loss, this would strongly suggest the fault lies with UPF's network egress or the common network fabric, falsifying the rtpengine-specific hypothesis.",
          "conflates_with": []
        }
      ],
      "notes": "This plan uses a direct metric from the suspect component (rtpengine.errors_per_second) and a pair of compositional path probes to isolate whether the fault is at the rtpengine application level or in the underlying network path. This directly addresses the feedback from the previous rejection."
    },
    {
      "hypothesis_id": "h2",
      "hypothesis_statement": "The UPF is the source of the data plane failure, dropping GTP-U packets and preventing media from reaching the rtpengine. This aligns with the `upf_activity_during_calls_collapsed` event and is supported by two high-similarity prior cases.",
      "primary_suspect_nf": "upf",
      "probes": [
        {
          "tool": "get_dp_quality_gauges",
          "args_hint": "Check UPF packet rates on N3 (towards gNB) and N6 (towards rtpengine) interfaces.",
          "expected_if_hypothesis_holds": "There is a significant mismatch in packet rates between ingress and egress interfaces (e.g., N6 ingress vs N3 egress for downlink), or rates on all interfaces are collapsed despite active calls.",
          "falsifying_observation": "Packet rates on UPF's ingress and egress interfaces are balanced and consistent with active call volume, indicating UPF is not the source of packet drops.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "from='rtpengine', to_ip='upf'",
          "expected_if_hypothesis_holds": "No significant packet loss or latency is observed, indicating the network path to UPF is healthy and consistent with the hypothesis that UPF itself is the problem.",
          "falsifying_observation": "High packet loss or latency is observed, suggesting the issue is on the network path to UPF, not a packet dropping issue within UPF.",
          "conflates_with": [
            "rtpengine's networking stack",
            "the network fabric between rtpengine and upf"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "from='rtpengine', to_ip='pcscf'",
          "expected_if_hypothesis_holds": "No significant packet loss or latency is observed. If the path to UPF also shows no loss, it strengthens the hypothesis that packet loss is occurring within UPF's logic.",
          "falsifying_observation": "High packet loss or latency is observed. If the path to UPF also shows high loss, it points to a problem with rtpengine's network egress or the adjacent fabric, rather than a problem specific to UPF.",
          "conflates_with": []
        }
      ],
      "notes": "This plan checks the suspect component's own counters for evidence of packet loss and uses a pair of compositional path probes to distinguish between a fault within UPF versus a fault in the network path leading to it. This structure correctly addresses the prior rejection feedback."
    }
  ]
}
